24 以下程序的输出结果是______。

main()
{int x=2,y=-1,z=2;
if(x<y)
if(y<0) z=0;
else z+=1;
printf("%d\n",z);
}
A)3    B)2    C)1    D)0

30 以下程序的运行结果是______。

main()
{int k=4,a=3,b=2,c=1;
printf("\n%d\n",k<a?k:c<b?c:a);
}
A)4    B)3    C)2    D)1

32 阅读以下程序，则执行下面语句后m的值是______。

int w=1,x=2,y=3,z=4,m;
m=w<x?w:x;
m=m<y?m:y;
m=m<z?m:z;
A)1    B)2    C)3    D)4

23 下面程序的运行结果是______。

#include <stdio.h>

main()

{int y=10;

do {y--;}while(--y);

printf("%d\n",y--);

}

若有以下程序:

nain(){

int x,y,z;

$$
x = y = 1;
$$

$$
z = x + +, y + +, + + y;
$$

printf("%d,%d,%d\n",z,y,x);

}

以下函数的功能是,通过键盘输入数据,为数组中的所有元素赋值。

#define N 10

void arrin(int x[N]){

int i = 0;

while(i
switch(i){
 case 1: printf("%d",i);
 case 2: printf("%d",i);
 default:printf("%d",i);
}
}
}

